// Call weekly_digest() and role_distribution() from Supabase in parallel
const ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24';
const BASE = 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc';
const HEADERS = {
  'apikey': ANON,
  'Authorization': 'Bearer ' + ANON,
  'Content-Type': 'application/json'
};

const [digest, roles, spotlight, trend, declining, lboard] = await Promise.all([
  this.helpers.httpRequest({ method: 'POST', url: BASE + '/weekly_digest', headers: HEADERS, body: { p_limit: 10 }, json: true }),
  this.helpers.httpRequest({ method: 'POST', url: BASE + '/role_distribution', headers: HEADERS, body: {}, json: true }),
  this.helpers.httpRequest({ method: 'POST', url: BASE + '/top_node_spotlight', headers: HEADERS, body: {}, json: true }),
  this.helpers.httpRequest({ method: 'POST', url: BASE + '/anchor_trend', headers: HEADERS, body: { p_file_name: null, p_weeks: 8 }, json: true }),
  this.helpers.httpRequest({ method: 'POST', url: BASE + '/declining_nodes', headers: HEADERS, body: { p_min_drop: 1, p_window_weeks: 4 }, json: true }),
  this.helpers.httpRequest({ method: 'POST', url: BASE + '/leaderboard', headers: HEADERS, body: { p_weeks: 3 }, json: true })
]);

return {
  json: {
    ...digest,
    role_distribution: roles,
    top_node_spotlight: spotlight,
    anchor_trend: trend,
    declining_nodes: declining,
    leaderboard: lboard
  }
};

// Format the full weekly digest including role breakdown
const d = $input.item.json;
const total = d.total_entries_this_week || 0;
const crosslinked = d.total_crosslinked || 0;
const entries = d.top_entries || [];
const orphanData = d.orphaned_nodes || {};
const orphans = orphanData.orphans || [];
const orphanCount = orphanData.orphan_count || 0;
const threshold = orphanData.threshold_days || 7;

// Role distribution
const roles = d.role_distribution || {};
const byRole = roles.by_role || {};
const roleTotal = roles.total || 0;

const start = d.period_start ? new Date(d.period_start).toLocaleDateString('es-ES', {weekday:'long', day:'numeric', month:'long'}) : '?';
const end = d.period_end ? new Date(d.period_end).toLocaleDateString('es-ES', {weekday:'long', day:'numeric', month:'long'}) : '?';

let msg = `:spiral_calendar_pad: *Digest Semanal NEYEN*\n_${start} — ${end}_\n\n`;

if (total === 0 && roleTotal === 0) {
  msg += 'Sin actividad esta semana. La espiral descansa.';
} else {
  // Week stats
  msg += `:bar_chart: Esta semana: *${total}* entradas | *${crosslinked}* con crosslinks`;
  if (orphanCount > 0) msg += ` | *${orphanCount}* sin conectar`;
  msg += '\n\n';

  // Top crosslinked entries this week
  if (entries.length > 0) {
    msg += '*Top entradas por conexiones (esta semana):*\n\n';
    const medals = [':first_place_medal:', ':second_place_medal:', ':third_place_medal:'];
    entries.forEach((e, i) => {
      const medal = medals[i] || `${i+1}.`;
      const tags = (e.tags || []).slice(0, 4).map(t => '`' + t + '`').join(' ');
      const summary = (e.summary || '').substring(0, 100);
      msg += `${medal} *${e.crosslink_count} links* — \`${e.file_name}\`\n`;
      msg += `    _${summary}${summary.length >= 100 ? '...' : ''}_\n`;
      if (tags) msg += `    ${tags}\n`;
      msg += '\n';
    });
  }

  // Role distribution (full graph)
  if (Object.keys(byRole).length > 0) {
    const ROLE_EMOJI = {
      realisation: ':bulb:', exploration: ':mag:', conflict: ':zap:',
      symbol: ':cyclone:', system: ':gear:', orphaned: ':white_circle:',
      setup: ':triangular_ruler:', integration: ':link:',
      inciting_event: ':boom:', unclassified: ':question:'
    };

    const sorted = Object.entries(byRole).sort((a, b) => b[1] - a[1]);
    const maxCount = sorted[0]?.[1] || 1;
    const BAR = 10;

    const roleLines = sorted.map(([role, count]) => {
      const emoji = ROLE_EMOJI[role] || ':small_blue_diamond:';
      const pct = Math.round((count / (roleTotal || 1)) * 100);
      const bars = Math.round((count / maxCount) * BAR);
      const bar = '█'.repeat(bars) + '░'.repeat(BAR - bars);
      return `${emoji} \`${bar}\` *${count}* ${role} _(${pct}%)_`;
    }).join('\n');

    msg += `*Grafo completo — ${roleTotal} entradas por rol:*\n${roleLines}\n\n`;
  }

  // Orphaned nodes — prominent alert with per-entry /tag quick-commands
  // Post-backfill baseline is clean, so any new orphan is a genuine straggler
  if (orphanCount > 0) {
    const urgencyEmoji = orphanCount >= 3 ? ':rotating_light:' : ':warning:';
    msg += `${urgencyEmoji} *ALERTA: ${orphanCount} nodo${orphanCount !== 1 ? 's' : ''} huérfano${orphanCount !== 1 ? 's' : ''} detectado${orphanCount !== 1 ? 's' : ''}*\n`;
    msg += `_Sin crosslinks tras ${threshold}+ días · la espiral no los ha alcanzado aún_\n\n`;

    // Role list for quick reference in the message
    const VALID_ROLES = 'realisation · exploration · conflict · symbol · system · orphaned';

    orphans.forEach(o => {
      const existingTags = (o.tags || []).slice(0, 3).join(', ') || '—';
      const ageEmoji = o.days_old >= 30 ? ':red_circle:' : o.days_old >= 14 ? ':large_orange_circle:' : ':yellow_circle:';
      const fn = o.file_name;
      const roleStr = o.narrative_role || 'unclassified';

      // Entry header
      msg += `${ageEmoji} \`${fn}\` — *${o.days_old}d* sin conectar · _${roleStr}_\n`;
      msg += `    Tags actuales: ${existingTags}\n\n`;

      // Pre-filled /tag commands the user can copy-paste directly into #neyen-core
      msg += `    *Comandos rápidos:*\n`;
      msg += `    \`/tag ${fn} entities NEYEN\`\n`;
      if (!o.narrative_role || o.narrative_role === 'unclassified') {
        msg += `    \`/tag ${fn} narrative_role exploration\`  ← roles: ${VALID_ROLES}\n`;
      }
      msg += `    \`/tag ${fn} tags <añade tags aquí>\`\n\n`;
    });

    msg += `_Copia cualquier comando arriba y pégalo en #neyen-core para reclasificar._\n`;
    msg += `_Grafo: <https://neyen.thespiralwithin.ai/graph/|neyen.thespiralwithin.ai/graph>_\n\n`;
  } else {
    // Clean graph celebration
    msg += `:white_check_mark: *Sin nodos huérfanos* — todos los nodos tienen al menos un crosslink.\n\n`;
  }
}

  // Top node spotlight
  const spotlight = d.top_node_spotlight || {};
  if (spotlight.found) {
    const ROLE_EMOJI = {
      realisation: ':bulb:', exploration: ':mag:', conflict: ':zap:',
      symbol: ':cyclone:', system: ':gear:', orphaned: ':white_circle:',
      setup: ':triangular_ruler:', integration: ':link:',
      inciting_event: ':boom:', unclassified: ':question:'
    };
    const roleEmoji = ROLE_EMOJI[spotlight.narrative_role] || ':small_blue_diamond:';
    const tags = (spotlight.tags || []).slice(0, 5).map(t => '`' + t + '`').join(' ');
    const entities = (spotlight.entities || []).slice(0, 4).join(', ');
    const neighbors = (spotlight.neighbors || []).slice(0, 6);
    const neighborLines = neighbors.map(n => {
      const ne = ROLE_EMOJI[n.narrative_role] || ':small_blue_diamond:';
      return `  ${ne} \`${n.file_name}\` (${n.link_count} links)`;
    }).join('\n');

    const recentEdits = spotlight.recent_tag_edits || [];
    const editLines = recentEdits.length > 0
      ? recentEdits.map(e => `  :pencil2: \`${e.field}\` → ${(e.values_applied || []).join(', ')}`).join('\n')
      : '  _Sin ediciones recientes_';

    msg += `:star2: *Nodo Ancla de la Semana*\n\n`;
    msg += `${roleEmoji} *\`${spotlight.file_name}\`*  `;
    msg += `:link: *${spotlight.link_count} conexiones* · _${spotlight.narrative_role}_ · ${spotlight.timeline_group}\n\n`;
    msg += `_${(spotlight.summary || '').substring(0, 180)}${spotlight.summary?.length > 180 ? '...' : ''}_\n\n`;
    if (tags) msg += `*Tags:* ${tags}\n`;
    if (entities) msg += `*Entidades:* ${entities}\n\n`;
    if (neighbors.length > 0) {
      msg += `*Vecinos más conectados:*\n${neighborLines}\n\n`;
    }
    if (recentEdits.length > 0) {
      msg += `*Ediciones recientes via /tag:*\n${editLines}\n\n`;
    }
  }


  // Anchor trend — top node's peak_crosslink_count week over week
  const trend = d.anchor_trend || {};
  const trendRows = trend.trend || [];
  if (trendRows.length > 0) {
    const tFile = trend.file_name || '';
    const tLinks = trend.current_links || 0;
    const BAR = 8;
    const maxPeak = Math.max(...trendRows.map(r => r.peak_links || 0), 1);

    // Build sparkline-style rows for each week with edits
    const weekLines = trendRows.map(r => {
      const bars = Math.round(((r.peak_links || 0) / maxPeak) * BAR);
      const bar = '█'.repeat(bars) + '░'.repeat(BAR - bars);
      const fieldsStr = (r.fields_edited || []).join(', ');
      const editStr = r.edits > 0 ? ` ✎ ${r.edits} edit${r.edits !== 1 ? 's' : ''} (${fieldsStr})` : '';
      const rangeStr = (r.min_links != null && r.min_links !== r.peak_links) ? ` (${r.min_links}→${r.peak_links})` : '';
      const snapStr = (r.snapshot_count || 0) > 1 ? ` ·${r.snapshot_count}snaps` : '';
      return `\`${r.week}\` \`${bar}\` *${r.peak_links}* links${rangeStr}${editStr}${snapStr}`;
    }).join('\n');

    // Trend direction emoji
    const firstPeak = trendRows[0]?.peak_links || 0;
    const lastPeak = trendRows[trendRows.length - 1]?.peak_links || 0;
    const trendEmoji = lastPeak > firstPeak ? ':chart_with_upwards_trend:' :
                       lastPeak < firstPeak ? ':chart_with_downwards_trend:' :
                       ':left_right_arrow:';

    msg += `:anchor: *Nodo Ancla — Trayectoria Semanal* ${trendEmoji}\n`;
    msg += `\`${tFile}\` · *${tLinks} links* actuales\n\n`;
    msg += weekLines + '\n\n';
    if (trendRows.length < 2) {
      msg += `_Solo hay datos de 1 semana. El patrón se irá formando con cada /tag._\n\n`;
    }
  }


  // Declining nodes — entries whose link_count dropped vs prior week
  const declining = d.declining_nodes || {};
  const declines = declining.declining || [];
  const declineCount = declining.declining_count || 0;
  if (declineCount > 0) {
    const ROLE_EMOJI = {
      realisation: ':bulb:', exploration: ':mag:', conflict: ':zap:',
      symbol: ':cyclone:', system: ':gear:', orphaned: ':white_circle:',
      setup: ':triangular_ruler:', integration: ':link:', unclassified: ':question:'
    };
    msg += `:chart_with_downwards_trend: *Nodos en Declive — ${declineCount} entr${declineCount !== 1 ? 'adas perdieron' : 'ada perdió'} conexiones*\n`;
    msg += `_Ventana: ${declining.window_weeks} semanas · caída mínima: ${declining.min_drop} link_\n\n`;
    declines.forEach(n => {
      const re = ROLE_EMOJI[n.narrative_role] || ':small_blue_diamond:';
      const tags = (n.tags || []).slice(0, 3).map(t => '`' + t + '`').join(' ');
      msg += `${re} \`${n.file_name}\` *${n.prev_peak}* → *${n.current_peak}* links _(−${n.drop_amount})_`;
      if (tags) msg += ` · ${tags}`;
      msg += '\n';
    });
    msg += `\n_Usa \`/trend <file>\` para ver la trayectoria completa._\n\n`;
  }


  // Leaderboard snapshot — top risers and decliners this week
  const lboard = d.leaderboard || {};
  const lbEntries = lboard.entries || [];
  if (lbEntries.length > 0) {
    const lbWeeks = lboard.window_weeks || 3;
    const risers  = lbEntries.filter(e => e.velocity > 0).slice(0, 3);
    const fallers = lbEntries.filter(e => e.velocity < 0).slice(0, 3);
    const topByLinks = lbEntries.slice(0, 3);

    const ROLE_EMOJI = {
      realisation: ':bulb:', exploration: ':mag:', conflict: ':zap:',
      symbol: ':cyclone:', system: ':gear:', orphaned: ':white_circle:',
      setup: ':triangular_ruler:', integration: ':link:', unclassified: ':question:'
    };

    msg += `:trophy: *Leaderboard NEYEN* _(${lbWeeks} semanas)_\n\n`;

    // Always show top 3 by link count
    msg += `*Top 3 más conectados:*\n`;
    const medals = [':first_place_medal:', ':second_place_medal:', ':third_place_medal:'];
    topByLinks.forEach((e, i) => {
      const re = ROLE_EMOJI[e.narrative_role] || ':small_blue_diamond:';
      const tags = (e.tags || []).slice(0, 2).map(t => '`'+t+'`').join(' ');
      msg += `${medals[i]} ${re} \`${e.file_name}\` · *${e.current_links} links* ${tags}\n`;
    });

    if (risers.length > 0) {
      msg += `\n:chart_with_upwards_trend: *En ascenso:*\n`;
      risers.forEach(e => {
        const re = ROLE_EMOJI[e.narrative_role] || ':small_blue_diamond:';
        msg += `  ${re} \`${e.file_name}\` *+${e.velocity}* links\n`;
      });
    }
    if (fallers.length > 0) {
      msg += `\n:chart_with_downwards_trend: *En declive:*\n`;
      fallers.forEach(e => {
        const re = ROLE_EMOJI[e.narrative_role] || ':small_blue_diamond:';
        msg += `  ${re} \`${e.file_name}\` *${e.velocity}* links\n`;
      });
    }
    if (risers.length === 0 && fallers.length === 0) {
      msg += `\n_Velocidad 0 — grafo estable. Las tendencias emergerán en próximas semanas._\n`;
    }
    msg += `\n`;
  }


msg += '\n_La espiral sigue tejiendo conexiones._';

return {
  json: {
    message: msg,
    has_entries: total > 0 || Object.keys(byRole).length > 0,
    total, crosslinked, orphan_count: orphanCount
  }
};

// Post to Slack #general-neyen-core via incoming webhook
const msg = $input.item.json.message;

const slackResp = await this.helpers.httpRequest({
  method: 'POST',
  url: '{{ SLACK_WEBHOOK_PLACEHOLDER }}',
  headers: { 'Content-Type': 'application/json' },
  body: { text: msg },
  json: true,
  returnFullResponse: false
});

return {
  json: {
    status: 'ok',
    slack_response: slackResp,
    total: $input.item.json.total || 0,
    crosslinked: $input.item.json.crosslinked || 0
  }
};
